//! 🔀️ Variant selection retains actual original discriminators and bounded schema comparisons.
use crate::{NativeDecodeControl,OriginalReceivingPrimary,RetainedWorkOutcome,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,retained_clone::{RetainedCloneBinding,RetainedCloneRef,retained_clone_grant_admits},owned::{NativeRecordMatcher,NativeRecordSchema,NativeSchemaLeaf,NativeSchemaKeySource,NativeFieldMatch,tree::{NativeValueSource,NativeTreeKind,fixed,receipt,invalid,nested,child_grant}}};
/// 🧾️ Generated borrowed tables distinguish all, unit and payload variants without constructing mirror owners.
#[derive(Clone,Copy)]pub struct NativeVariantSpec{pub all:fn(usize)->Option<NativeRecordSchema>,pub units:fn(usize)->Option<NativeRecordSchema>,pub data:fn(usize)->Option<NativeRecordSchema>,pub count:usize,pub tag:Option<fn(usize)->Option<NativeRecordSchema>>}
/// 🎯️ Direct authored payloads retain their genuine source path independently from canonical wire carriers.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct NativeVariantSelection{pub index:usize,pub direct:bool}
pub struct NativeVariantSelector<I:NativeValueSource+?Sized>{binding:Option<RetainedCloneBinding>,matcher:Option<NativeRecordMatcher<I>>,spec:NativeVariantSpec,selection:Option<NativeVariantSelection>,tag:Option<usize>,scan:usize,phase:u8,direct:bool,closing:bool,failed:bool}
impl<I:NativeValueSource+?Sized>NativeVariantSelector<I>{
 pub fn new(spec:NativeVariantSpec)->Self{Self{binding:None,matcher:None,spec,selection:None,tag:None,scan:0,phase:0,direct:false,closing:false,failed:false}}
 pub fn result(&self)->Option<NativeVariantSelection>{self.selection}
 pub fn validate_input(&self,input:RetainedCloneRef<'_,I>)->Result<(),ValueError>{input.check_binding(&self.binding)?;Ok(())}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.selection.is_some()||self.failed{return Ok(Default::default())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}if let Some(matcher)=self.matcher.as_ref(){if self.phase==3{return if matcher.terminal_is_empty(){Ok(fixed(0))}else{nested(matcher.close_demands(body)?,0)}}if matcher.result().is_none(){return nested(matcher.demands(input,body)?,0)}}Ok(fixed(0))}
 pub fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{if self.failed{return RetainedWorkOutcome{result:Err(invalid().into()),work:0}}if self.selection.is_some(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let mut work=0;let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;if self.binding.is_none(){let turn=input.bind(&mut self.binding,g);let turn=control.receive_retained_work(g,crate::RetainedWorkOutcome{result:turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())),work:turn.work});work=turn.work;return turn.result.map_err(Into::into)}
  if let Some(matcher)=self.matcher.as_mut(){if self.phase==3&&!matcher.terminal_is_empty(){let turn=matcher.close_step(child_grant(g,0));work=turn.work;let turn=control.receive_retained_work(g,turn);return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.phase!=3&&matcher.result().is_none(){let turn=matcher.advance(input,control,body,child_grant(g,0));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}}
  work=1;match self.phase{
   0=>self.phase=1,
   1=>{if input.get().variant_tag().is_some(){self.direct=true;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::VariantTag));self.phase=4;}else if self.spec.tag.is_some(){self.phase=2;}else if input.get().tree_kind()==Some(NativeTreeKind::Text){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::Text));self.phase=4;}else if input.get().tree_kind().is_none(){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::EnumOrdinal));self.phase=4;}else{if input.get().record_len()?!=1{return Err(invalid().into())}self.matcher=Some(NativeRecordMatcher::new(self.spec.data,self.spec.count,NativeSchemaKeySource::RecordName(0)));self.phase=4;}},
   2=>{if let Some(matcher)=self.matcher.as_mut(){match matcher.result().ok_or_else(invalid)?{NativeFieldMatch::Field(_)=>{if self.tag.is_some(){self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.tag=Some(self.scan);},NativeFieldMatch::Ambiguous=>{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())},NativeFieldMatch::Missing=>{}}matcher.begin_close();self.phase=3;}else{let count=input.get().record_len()?;if self.scan==count{let tag=self.tag.ok_or_else(invalid)?;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::RecordText(tag)));self.phase=4;}else{self.matcher=Some(NativeRecordMatcher::new(self.spec.tag.ok_or_else(invalid)?,1,NativeSchemaKeySource::Record(self.scan)));}}},
   3=>{self.matcher=None;self.scan+=1;self.phase=2;},
   4=>{let NativeFieldMatch::Field(index)=self.matcher.as_ref().ok_or_else(invalid)?.result().ok_or_else(invalid)?else{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())};if index>=self.spec.count{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.selection=Some(NativeVariantSelection{index,direct:self.direct});self.phase=5;},
   _=>return Err(invalid().into()),
  }Ok(if self.selection.is_some(){RetainedCloneStep::Complete(receipt(fixed(0)))}else{RetainedCloneStep::Progress(receipt(fixed(0)))})})();let result=result;RetainedWorkOutcome{result,work}}
 /// 🧷️ Drains completed matcher scratch while retaining the genuine original binding for final publication checks.
 pub fn begin_settlement(&mut self){if let Some(matcher)=self.matcher.as_mut(){matcher.begin_close();}}
 pub fn settled(&self)->bool{self.matcher.is_none()}
 pub fn settlement_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(matcher)=self.matcher.as_ref(){if matcher.terminal_is_empty(){Ok(fixed(0))}else{nested(matcher.close_demands(body)?,0)}}else{Ok(Default::default())}}
 pub fn settle_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{if self.matcher.is_none(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.settlement_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let matcher=self.matcher.as_mut().unwrap();if matcher.terminal_is_empty(){self.matcher=None;return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(fixed(0)))),work:1}}matcher.close_step(child_grant(g,0))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(matcher)=self.matcher.as_mut(){matcher.begin_close();}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.matcher.is_some(){return self.settlement_demand(body)}if self.binding.is_some(){return RetainedCloneBinding::close_demand(&self.binding,body)}if self.phase!=6{return Ok(fixed(0))}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.matcher.is_some(){let turn=self.settle_step(g);work=turn.work;return turn.result}if self.binding.is_some(){let turn=RetainedCloneBinding::close_one(&mut self.binding,g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}self.selection=None;self.tag=None;self.failed=false;self.phase=6;work=1;Ok(RetainedCloneStep::Complete(receipt(fixed(0))))})();RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.matcher.is_none()&&(self.phase==6||self.phase==0)}
}
impl<I:NativeValueSource+?Sized>Drop for NativeVariantSelector<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native variant selector requires funded closure")}}

#[path="🔢️unit/🦀️.rs"]mod unit;
pub use unit::{NativeUnitVariants,NativeUnitEnumReceiver};
